# setup_default_AgeSpecific ----
## Setup ----
data <- FIMS::FIMSFrame(data_big)
n_ages <- FIMS::get_n_ages(data)
ages <- FIMS::get_ages(data)

## IO correctness ----
test_that("`setup_default_AgeSpecific()` works with correct inputs", {
  result <- FIMS:::setup_default_AgeSpecific(data = data)

  #' @description Test that output has the expected labels and default values.
  expect_s3_class(result, "tbl_df")
  expect_equal(
    result[["label"]],
    rep(x = "logit_sel_at_age", times = n_ages)
  )
  expect_equal(
    result[["value"]],
    qlogis(1 / (1 + (exp(-1 * (ages - 2)))))
  )

  clear()
})

